from itertools import product
import random

def candidate(data):
    n, edges = data['n'], data['edges']
    target = tuple(data['balance'])
    if sum(target) or any(e['lower'] > e['upper'] for e in edges):
        return None
    split = len(edges)//2
    def enumerate_half(part):
        for f in product(*(range(e['lower'], e['upper']+1) for e in part)):
            net, cost = [0]*n, 0
            for e, x in zip(part, f):
                net[e['u']] += x
                net[e['v']] -= x
                cost += x*e['cost']
            yield tuple(net), cost, f
    right = {}
    for net,c,f in enumerate_half(edges[split:]):
        if net not in right or (c,f)<right[net]: right[net]=(c,f)
    best=None
    for net,c,f in enumerate_half(edges[:split]):
        r=right.get(tuple(t-x for t,x in zip(target,net)))
        if r is not None:
            pair=(c+r[0],f+r[1])
            if best is None or pair<best: best=pair
    return None if best is None else list(best[1])

def solve(data):
    rng=random.Random(187)
    for trial in range(400):
        n=rng.randint(1,6)
        edges=[]
        for _ in range(rng.randint(0,7)):
            lo=rng.randint(0,3)
            edges.append(dict(u=rng.randrange(n),v=rng.randrange(n),lower=lo,upper=rng.randint(lo,3),cost=rng.randint(-4,4)))
        b=[0]*n
        for e in edges:
            x=rng.randint(e['lower'],e['upper'])
            b[e['u']]+=x
            b[e['v']]-=x
        if trial%3==0:
            b[rng.randrange(n)]+=1
            b[rng.randrange(n)]-=1
        d=dict(n=n,edges=edges,balance=b)
        best=None
        for f in product(*(range(e['lower'],e['upper']+1) for e in edges)):
            net=[0]*n
            c=0
            for e,x in zip(edges,f):
                net[e['u']]+=x
                net[e['v']]-=x
                c+=x*e['cost']
            if net==b and (best is None or (c,f)<best):best=(c,f)
        expected=None if best is None else list(best[1])
        actual=candidate(d)
        if actual!=expected:return dict(input=d,expected=expected,actual=actual)
    return {'randomized_exhaustive_comparisons_passed':400}

