import sys
def solve(data):
    n = data["n"]; edges = data["edges"]; bal = data["balance"]
    m = len(edges)
    E = [(e["u"], e["v"], e["lower"], e["upper"], e["cost"]) for e in edges]
    # suffix min/max contributions per vertex for pruning
    # minout[i][v], maxout[i][v]: range of net outflow at v achievable by edges i..m-1
    lo = [[0]*n for _ in range(m+1)]
    hi = [[0]*n for _ in range(m+1)]
    for i in range(m-1, -1, -1):
        u, v, l, up, c = E[i]
        for w in range(n):
            lo[i][w] = lo[i+1][w]; hi[i][w] = hi[i+1][w]
        if u != v:
            lo[i][u] += l; hi[i][u] += up
            lo[i][v] -= up; hi[i][v] -= l
    cur = [0]*n
    best = [None, None]
    flow = [0]*m
    sys.setrecursionlimit(10000)
    def feas(i):
        for w in range(n):
            need = bal[w] - cur[w]
            if need < lo[i][w] or need > hi[i][w]:
                return False
        return True
    def rec(i, cost):
        if i == m:
            if all(cur[w] == bal[w] for w in range(n)):
                if best[0] is None or cost < best[0]:
                    best[0] = cost; best[1] = flow[:]
            return
        if not feas(i):
            return
        u, v, l, up, c = E[i]
        for f in range(l, up+1):
            flow[i] = f
            if u != v:
                cur[u] += f; cur[v] -= f
            rec(i+1, cost + f*c)
            if u != v:
                cur[u] -= f; cur[v] += f
    rec(0, 0)
    return best[1]

