import itertools, random, sys
def solve_mine(data):
    n = data["n"]; edges = data["edges"]; bal = data["balance"]
    m = len(edges)
    E = [(e["u"], e["v"], e["lower"], e["upper"], e["cost"]) for e in edges]
    lo = [[0]*n for _ in range(m+1)]
    hi = [[0]*n for _ in range(m+1)]
    for i in range(m-1, -1, -1):
        u, v, l, up, c = E[i]
        for w in range(n):
            lo[i][w] = lo[i+1][w]; hi[i][w] = hi[i+1][w]
        if u != v:
            lo[i][u] += l; hi[i][u] += up
            lo[i][v] -= up; hi[i][v] -= l
    cur = [0]*n
    best = [None, None]
    flow = [0]*m
    def feas(i):
        for w in range(n):
            need = bal[w] - cur[w]
            if need < lo[i][w] or need > hi[i][w]:
                return False
        return True
    def rec(i, cost):
        if i == m:
            if all(cur[w] == bal[w] for w in range(n)):
                if best[0] is None or cost < best[0]:
                    best[0] = cost; best[1] = flow[:]
            return
        if not feas(i):
            return
        u, v, l, up, c = E[i]
        for f in range(l, up+1):
            flow[i] = f
            if u != v:
                cur[u] += f; cur[v] -= f
            rec(i+1, cost + f*c)
            if u != v:
                cur[u] -= f; cur[v] += f
    rec(0, 0)
    return best[1]

def naive(data):
    n=data["n"]; E=data["edges"]; bal=data["balance"]
    best=None
    for fl in itertools.product(*[range(e["lower"],e["upper"]+1) for e in E]):
        net=[0]*n
        for f,e in zip(fl,E):
            net[e["u"]]+=f; net[e["v"]]-=f
        if net!=bal: continue
        c=sum(f*e["cost"] for f,e in zip(fl,E))
        if best is None or c<best[0]: best=(c,list(fl))
    return None if best is None else best[1]

def solve(data):
    random.seed(data)
    bad=0
    for t in range(400):
        n=random.randint(1,4); m=random.randint(0,6)
        E=[]
        for _ in range(m):
            l=random.randint(0,3); u=random.randint(l,3)
            E.append({"u":random.randint(0,n-1),"v":random.randint(0,n-1),"lower":l,"upper":u,"cost":random.randint(-4,4)})
        # make balance sometimes feasible
        if random.random()<0.6:
            fl=[random.randint(e["lower"],e["upper"]) for e in E]
            bal=[0]*n
            for f,e in zip(fl,E): bal[e["u"]]+=f; bal[e["v"]]-=f
        else:
            bal=[random.randint(-2,2) for _ in range(n)]
        d={"n":n,"edges":E,"balance":bal}
        if solve_mine(d)!=naive(d): bad+=1
    return bad

