        return None

    def enumerate_half(part):
        best = {}
        net = [0] * n
        flows = []

        def visit(i, cost):
            if i == len(part):
                key = tuple(net)
                value = (cost, tuple(flows))
                if key not in best or value < best[key]:
                    best[key] = value
