def solve(data):
    n = data['n']
    edges = data['edges']
    balance = tuple(data['balance'])
    if sum(balance) != 0:
        return None
    for e in edges:
        if e['lower'] > e['upper']:
            return None
    m = len(edges)
    k = m // 2

    def enumerate_half(part):
        net = [0] * n
        flow = []
        def rec(i, cost):
            if i == len(part):
                yield tuple(net), cost, tuple(flow)
                return
            e = part[i]
            u, v, c = e['u'], e['v'], e['cost']
            for f in range(e['lower'], e['upper'] + 1):
                net[u] += f
                net[v] -= f
                flow.append(f)
                yield from rec(i + 1, cost + f * c)
                flow.pop()
                net[u] -= f
                net[v] += f
        yield from rec(0, 0)

    left = {}
    for net, cost, flow in enumerate_half(edges[:k]):
        candidate = (cost, flow)
        if net not in left or candidate < left[net]:
            left[net] = candidate
    best = None
    for net, cost, flow in enumerate_half(edges[k:]):
        needed = tuple(balance[v] - net[v] for v in range(n))
        if needed in left:
            lc, lf = left[needed]
            candidate = (lc + cost, lf + flow)
            if best is None or candidate < best:
                best = candidate
    return None if best is None else list(best[1])

