import itertools

def solve(data):
    n = data["n"]
    edges = data["edges"]
    bal = data["balance"]
    m = len(edges)
    ranges = [range(e["lower"], e["upper"] + 1) for e in edges]
    for r in ranges:
        if len(r) == 0:
            return None
    us = [e["u"] for e in edges]
    vs = [e["v"] for e in edges]
    cs = [e["cost"] for e in edges]
    best = None
    bestcost = None
    # DFS in lexicographic order with pruning on remaining capacity
    # Precompute for suffix: per-vertex min/max net contribution
    suf_min = [[0]*n for _ in range(m+1)]
    suf_max = [[0]*n for _ in range(m+1)]
    for i in range(m-1, -1, -1):
        for v in range(n):
            suf_min[i][v] = suf_min[i+1][v]
            suf_max[i][v] = suf_max[i+1][v]
        lo, hi = edges[i]["lower"], edges[i]["upper"]
        if us[i] != vs[i]:
            suf_min[i][us[i]] += lo; suf_max[i][us[i]] += hi
            suf_min[i][vs[i]] -= hi; suf_max[i][vs[i]] -= lo
    suf_cmin = [0]*(m+1)
    for i in range(m-1, -1, -1):
        lo, hi = edges[i]["lower"], edges[i]["upper"]
        suf_cmin[i] = suf_cmin[i+1] + min(lo*cs[i], hi*cs[i])
    cur = [0]*m
    net = [0]*n

    def feasible(i):
        for v in range(n):
            need = bal[v] - net[v]
            if need < suf_min[i][v] or need > suf_max[i][v]:
                return False
        return True

    def dfs(i, cost):
        nonlocal best, bestcost
        if bestcost is not None and cost + suf_cmin[i] > bestcost:
            return
        if not feasible(i):
            return
        if i == m:
            if bestcost is None or cost < bestcost:
                bestcost = cost
                best = cur[:]
            return
        u, v, c = us[i], vs[i], cs[i]
        for f in ranges[i]:
            cur[i] = f
            if u != v:
                net[u] += f; net[v] -= f
            dfs(i+1, cost + f*c)
            if u != v:
                net[u] -= f; net[v] += f
    dfs(0, 0)
    return best

