def solve(data):
    groups = {}
    for event in data['events']:
        body = json.dumps(event, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
        groups.setdefault(event['id'], {})[body] = event
    events = {eid: next(iter(bodies.values())) for eid, bodies in groups.items() if len(bodies) == 1}

    # Grow from dependency-free events; cycles and missing dependencies never enter.
    ancestors = {}
    while True:
        changed = False
        for eid, event in events.items():
            if eid in ancestors:
                continue
            deps = event['deps']
            if all(dep in ancestors for dep in deps):
                reachable = set(deps)
                for dep in deps:
                    reachable.update(ancestors[dep])
                ancestors[eid] = reachable
                changed = True
        if not changed:
            break

    removed = set()
    for eid, reachable in ancestors.items():
        event = events[eid]
        if event['kind'] != 'remove':
            continue
        for target in event['targets']:
            if target in reachable:
                add = events[target]
                if add['kind'] == 'add' and add['key'] == event['key']:
                    removed.add(target)
    return {
        'eligible': sorted(ancestors),
        'live': sorted(eid for eid in ancestors if events[eid]['kind'] == 'add' and eid not in removed)
    }

