        groups.setdefault(event['id'], {})[body] = event
    events = {eid: next(iter(b.values())) for eid, b in groups.items() if len(b) == 1}
    ancestors = {}
    while True:
        changed = False
        for eid, event in events.items():
            if eid not in ancestors and all(d in ancestors for d in event['deps']):
                closure = set(event['deps'])
                for d in event['deps']:
                    closure.update(ancestors[d])
                ancestors[eid] = closure
                changed = True
        if not changed:
            break
    removed = set()
    for eid in ancestors:
        e = events[eid]
        if e['kind'] == 'remove':
            for t in e['targets']:
                if t in ancestors[eid] and events[t]['kind'] == 'add' and events[t]['key'] == e['key']:
                    removed.add(t)
    return {'eligible': sorted(ancestors), 'live': sorted(i for i in ancestors if events[i]['kind'] == 'add' and i not in removed)}

def oracle(data):
    groups = {}
    for e in data['events']:
        b = json.dumps(e, sort_keys=True)
        groups.setdefault(e['id'], {})[b] = e
    ev = {i: next(iter(g.values())) for i,g in groups.items() if len(g)==1}
    def valid(i, path):
        if i not in ev or i in path:
            return False
        return all(valid(d,path | {i}) for d in ev[i]['deps'])
    eligible = {i for i in ev if valid(i,set())}
    def reachable(i, t):
        return any(d == t or reachable(d,t) for d in ev[i]['deps'])
    live = []
    for i in eligible:
        if ev[i]['kind'] == 'add' and not any(ev[r]['kind']=='remove' and ev[r]['key']==ev[i]['key'] and i in ev[r]['targets'] and reachable(r,i) for r in eligible):
            live.append(i)
    return {'eligible': sorted(eligible), 'live': sorted(live)}

def solve(data):
    rng=random.Random(data['seed'])
    for trial in range(1500):
        n=rng.randrange(1,11)
        ids=['', 'é', 'a', 'a\u0000', '😀', '10','2','z','r','x'][:n]
        events=[]
        for i in ids:
            kind=rng.choice(['add','remove'])
            e={'id':i,'kind':kind,'key':rng.choice(['','x','y']),'deps':rng.choices(ids+['missing'],k=rng.randrange(4))}
            if kind=='remove':
                e['targets']=rng.choices(ids+['missing'],k=rng.randrange(4))
            events.append(e)
            if rng.random()<0.25:
                events.append(dict(reversed(list(e.items()))))
            if rng.random()<0.15:
                events.append(dict(e,key='conflict'))
        rng.shuffle(events)
        inp={'events':events}
        snapshot=json.dumps(inp)
        got=candidate(inp)
        expected=oracle(inp)
        if got!=expected or json.dumps(inp)!=snapshot:
            return {'trial':trial,'input':inp,'got':got,'expected':expected}
    return {'random_cases_passed':1500}

