import json

def solve(data):
    events = data.get("events", []) if isinstance(data, dict) else []
    bodies = {}
    order = []
    for ev in events:
        if not isinstance(ev, dict):
            continue
        eid = ev.get("id")
        if not isinstance(eid, str):
            continue
        canon = json.dumps(ev, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        if eid not in bodies:
            bodies[eid] = {}
            order.append(eid)
        if canon not in bodies[eid]:
            bodies[eid][canon] = ev
    # unambiguous events
    uniq = {}
    for eid, bs in bodies.items():
        if len(bs) == 1:
            uniq[eid] = next(iter(bs.values()))
    def deps_of(ev):
        d = ev.get("deps", [])
        if not isinstance(d, list):
            return None
        out = []
        for x in d:
            if not isinstance(x, str):
                return None
            out.append(x)
        return out
    depmap = {}
    for eid, ev in uniq.items():
        d = deps_of(ev)
        depmap[eid] = d
    # least fixpoint of eligibility
    eligible = set()
    changed = True
    while changed:
        changed = False
        for eid, d in depmap.items():
            if eid in eligible or d is None:
                continue
            ok = True
            for x in d:
                if x not in eligible:
                    ok = False
                    break
            if ok:
                eligible.add(eid)
                changed = True
    # ancestors
    anc_cache = {}
    def ancestors(eid):
        if eid in anc_cache:
            return anc_cache[eid]
        seen = set()
        stack = list(depmap.get(eid) or [])
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            if x in eligible:
                stack.extend(depmap.get(x) or [])
        anc_cache[eid] = seen
        return seen
    removed = set()
    for eid in eligible:
        ev = uniq[eid]
        if ev.get("kind") != "remove":
            continue
        targets = ev.get("targets", [])
        if not isinstance(targets, list):
            continue
        anc = ancestors(eid)
        for t in targets:
            if not isinstance(t, str) or t == eid:
                continue
            if t in eligible and t in anc:
                tev = uniq[t]
                if tev.get("kind") == "add" and tev.get("key") == ev.get("key"):
                    removed.add(t)
    live = [e for e in eligible if uniq[e].get("kind") == "add" and e not in removed]
    return {"eligible": sorted(eligible), "live": sorted(live)}

