def solve(data):
    jobs = sorted(data['jobs'], key=lambda j: j['id'])
    n = len(jobs)
    index = {j['id']: i for i, j in enumerate(jobs)}

    # An absent dependency receives an extra bit that can never be selected.
    requirements = []
    for job in jobs:
        mask = 0
        for dep in job.get('deps', []):
            mask |= 1 << index.get(dep, n)
        requirements.append(mask)

    blackouts = []
    for a, b in sorted(data.get('blackouts', [])):
        if a >= b:
            continue
        if blackouts and a <= blackouts[-1][1]:
            blackouts[-1][1] = max(blackouts[-1][1], b)
        else:
            blackouts.append([a, b])

    setup = data['setup']
    best_key = (0, 0, ())
    path = []

    def search(mask, time, family, value):
        nonlocal best_key
        key = (-value, time, tuple(path))
        if key < best_key:
            best_key = key

        for i, job in enumerate(jobs):
            bit = 1 << i
            if (mask & bit) or (requirements[i] & mask) != requirements[i]:
                continue
            start = max(job['release'], time + setup[family][job['family']])
            duration = job['duration']
            for a, b in blackouts:
                if start + duration <= a:
                    break
                if start < b:
                    start = b
            end = start + duration
            if end <= job['deadline']:
                path.append(job['id'])
                search(mask | bit, end, job['family'], value + job['value'])
                path.pop()

    search(0, 0, 0, 0)
    return list(best_key[2])

