def solve(data):
    events = data.get("events", []) if isinstance(data, dict) else []
    bodies = {}
    for ev in events:
        if not isinstance(ev, dict):
            continue
        eid = ev.get("id")
        if not isinstance(eid, str):
            continue
        canon = json.dumps(ev, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        bodies.setdefault(eid, {})
        if canon not in bodies[eid]:
            bodies[eid][canon] = ev
    uniq = {eid: next(iter(bs.values())) for eid, bs in bodies.items() if len(bs) == 1}
    def deps_of(ev):
        d = ev.get("deps", [])
        if not isinstance(d, list) or any(not isinstance(x, str) for x in d):
            return None
        return list(d)
    depmap = {eid: deps_of(ev) for eid, ev in uniq.items()}
    eligible = set()
    changed = True
    while changed:
        changed = False
        for eid, d in depmap.items():
            if eid in eligible or d is None:
                continue
            if all(x in eligible for x in d):
                eligible.add(eid); changed = True
    anc_cache = {}
    def ancestors(eid):
