def solve(data):
    jobs = data["jobs"]
    setup = data["setup"]
    # ignore empty blackouts [a,a): they contain no time points
    blackouts = [tuple(b) for b in data.get("blackouts", []) if b[0] < b[1]]
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    # dependency masks; None if impossible (absent dep or self dep)
    depmask = []
    for i, j in enumerate(jobs):
        m = 0
        ok = True
        for d in j.get("deps", []):
            if d not in idx or idx[d] == i:
                ok = False
                break
            m |= 1 << idx[d]
        depmask.append(m if ok else None)

    def earliest_start(s, d):
        changed = True
        while changed:
            changed = False
            for a, b in blackouts:
                if s < b and s + d > a:
                    s = b
                    changed = True
        return s

    best = [None]  # key tuple (-value, completion, seq)

    def dfs(mask, t, f, val, seq):
        key = (-val, t, list(seq))
        if best[0] is None or key < best[0]:
            best[0] = key
        for i, j in enumerate(jobs):
            if mask >> i & 1:
                continue
            dm = depmask[i]
            if dm is None or (dm & mask) != dm:
                continue
            s = max(j["release"], t + setup[f][j["family"]])
            s = earliest_start(s, j["duration"])
            c = s + j["duration"]
            if c > j["deadline"]:
                continue
            seq.append(j["id"])
            dfs(mask | (1 << i), c, j["family"], val + j["value"], seq)
            seq.pop()

    dfs(0, 0, 0, 0, [])
    return best[0][2]

