def solve(data):
    n = data['n']
    edges = data['edges']
    target = tuple(data['balance'])
    if sum(target) != 0:
        return None
    if any(e['lower'] > e['upper'] for e in edges):
        return None
    m = len(edges)
    cut = m // 2

    def assignments(start, end):
        net = [0] * n
        flow = []

        def visit(i, cost):
            if i == end:
                yield tuple(net), cost, tuple(flow)
                return
            e = edges[i]
            u, v, c = e['u'], e['v'], e['cost']
            for f in range(e['lower'], e['upper'] + 1):
                net[u] += f
                net[v] -= f
                flow.append(f)
                yield from visit(i + 1, cost + f * c)
                flow.pop()
                net[v] += f
                net[u] -= f

        yield from visit(start, 0)

    left = {}
    for net, cost, flow in assignments(0, cut):
        candidate = (cost, flow)
        if net not in left or candidate < left[net]:
            left[net] = candidate

    best = None
    for net, cost, flow in assignments(cut, m):
        needed = tuple(target[v] - net[v] for v in range(n))
        prefix = left.get(needed)
        if prefix is not None:
            candidate = (prefix[0] + cost, prefix[1] + flow)
            if best is None or candidate < best:
                best = candidate

    return None if best is None else list(best[1])

