import sys
def solve(data):
    n=data["n"]; edges=data["edges"]; bal=data["balance"]
    m=len(edges)
    lo=[e["lower"] for e in edges]; hi=[e["upper"] for e in edges]
    cs=[e["cost"] for e in edges]
    us=[e["u"] for e in edges]; vs=[e["v"] for e in edges]
    for i in range(m):
        if lo[i]>hi[i]: return None
    # suffix min/max contribution per vertex from edges i..m-1
    sufmin=[[0]*n for _ in range(m+1)]; sufmax=[[0]*n for _ in range(m+1)]
    for i in range(m-1,-1,-1):
        for v in range(n):
            sufmin[i][v]=sufmin[i+1][v]; sufmax[i][v]=sufmax[i+1][v]
        u,v=us[i],vs[i]
        if u!=v:
            sufmin[i][u]+=lo[i]; sufmax[i][u]+=hi[i]
            sufmin[i][v]-=hi[i]; sufmax[i][v]-=lo[i]
    # suffix min cost (ignoring balance) for bound
    sufc=[0]*(m+1)
    for i in range(m-1,-1,-1):
        c=cs[i]
        sufc[i]=sufc[i+1]+(c*hi[i] if c<0 else c*lo[i])
    net=[0]*n
    cur=[0]*m
    best=[None]; bestcost=[None]
    sys.setrecursionlimit(10000)
    def ok(i):
        for v in range(n):
            need=bal[v]-net[v]
            if need<sufmin[i][v] or need>sufmax[i][v]: return False
        return True
    def rec(i,cost):
        if bestcost[0] is not None and cost+sufc[i]>bestcost[0]: return
        if i==m:
            if bestcost[0] is None or cost<bestcost[0]:
                bestcost[0]=cost; best[0]=cur[:]
