from itertools import product


def solve(data):
    n = data['n']
    edges = data['edges']
    target = tuple(data['balance'])
    if sum(target) != 0:
        return None
    if any(e['lower'] > e['upper'] for e in edges):
        return None
    split = len(edges) // 2

    def possibilities(part):
        ranges = [range(e['lower'], e['upper'] + 1) for e in part]
        for flows in product(*ranges):
            net = [0] * n
            cost = 0
            for e, f in zip(part, flows):
                net[e['u']] += f
                net[e['v']] -= f
                cost += e['cost'] * f
            yield tuple(net), cost, flows

    # For any fixed prefix, only the best compatible suffix matters.
    right = {}
    for net, cost, flows in possibilities(edges[split:]):
        candidate = (cost, flows)
        if net not in right or candidate < right[net]:
            right[net] = candidate

    best = None
    for net, cost, flows in possibilities(edges[:split]):
        needed = tuple(target[v] - net[v] for v in range(n))
        other = right.get(needed)
        if other is not None:
            candidate = (cost + other[0], flows + other[1])
            if best is None or candidate < best:
                best = candidate
    return None if best is None else list(best[1])

