import json

def solve(data):
    events = data.get("events", [])
    bodies = {}
    for ev in events:
        eid = ev.get("id")
        canon = json.dumps(ev, sort_keys=True, separators=(",", ":"))
        bodies.setdefault(eid, {})[canon] = ev
    unamb = {eid: next(iter(b.values())) for eid, b in bodies.items() if len(b) == 1}
    # least fixpoint eligibility
    eligible = set()
    changed = True
    while changed:
        changed = False
        for eid, ev in unamb.items():
            if eid in eligible:
                continue
            deps = ev.get("deps") or []
            if all(d in eligible for d in deps):
                eligible.add(eid)
                changed = True
    # ancestors
    def ancestors(eid):
        seen = set()
        stack = list(unamb[eid].get("deps") or [])
        while stack:
            d = stack.pop()
            if d in seen or d not in unamb:
                continue
            seen.add(d)
            stack.extend(unamb[d].get("deps") or [])
        return seen
    removed = set()
    for eid in eligible:
        ev = unamb[eid]
        if ev.get("kind") != "remove":
            continue
        anc = ancestors(eid)
        for t in ev.get("targets") or []:
            if t in eligible and t != eid and t in anc:
                tev = unamb[t]
                if tev.get("kind") == "add" and tev.get("key") == ev.get("key"):
                    removed.add(t)
    live = [e for e in eligible if unamb[e].get("kind") == "add" and e not in removed]
    return {"eligible": sorted(eligible), "live": sorted(live)}

