    k = len(edges) // 2

    def enumerate_half(part):
        net = [0] * n
        flow = []

        def rec(i, cost):
            if i == len(part):
                yield tuple(net), cost, tuple(flow)
                return
            e = part[i]
            u, v, c = e['u'], e['v'], e['cost']
            for f in range(e['lower'], e['upper'] + 1):
                net[u] += f
                net[v] -= f
                flow.append(f)
                yield from rec(i + 1, cost + f * c)
                flow.pop()
                net[u] -= f
                net[v] += f

        yield from rec(0, 0)

