def solve(data):
    jobs = sorted(data['jobs'], key=lambda job: job['id'])
    n = len(jobs)
    indices = {job['id']: i for i, job in enumerate(jobs)}

    requirements = []
    for job in jobs:
        mask = 0
        for dep in job['deps']:
            # Bit n is never selected, so absent dependencies block a job.
            mask |= 1 << indices.get(dep, n)
        requirements.append(mask)

    blackouts = []
    for a, b in sorted(data['blackouts']):
        if b <= a:
            continue
        if blackouts and a <= blackouts[-1][1]:
            blackouts[-1][1] = max(blackouts[-1][1], b)
        else:
            blackouts.append([a, b])

    setup = data['setup']
    best_key = (0, 0, ())

    def search(mask, time, family, value, sequence):
        nonlocal best_key
        key = (-value, time, sequence)
        if key < best_key:
            best_key = key

        for i, job in enumerate(jobs):
            bit = 1 << i
            if (mask & bit) or (requirements[i] & mask) != requirements[i]:
                continue

            start = max(job['release'], time + setup[family][job['family']])
            duration = job['duration']
            for a, b in blackouts:
                if start + duration <= a:
                    break
                if start < b and start + duration > a:
                    start = b

