import json

def solve(data):
    events = data.get("events", [])
    bodies = {}
    for e in events:
        eid = e.get("id")
        if not isinstance(eid, str):
            continue
        canon = json.dumps(e, sort_keys=True, separators=(",", ":"))
        bodies.setdefault(eid, {})[canon] = e
    unamb = {}
    for eid, bs in bodies.items():
        if len(bs) == 1:
            unamb[eid] = next(iter(bs.values()))
    deps = {}
    for eid, e in unamb.items():
        d = e.get("deps") or []
        deps[eid] = [x for x in d if isinstance(x, str)] if isinstance(d, list) else []
        if not isinstance(d, list) or any(not isinstance(x, str) for x in d):
            deps[eid] = None  # malformed deps -> ineligible
    eligible = set()
    changed = True
    while changed:
        changed = False
        for eid in unamb:
            if eid in eligible or deps[eid] is None:
                continue
            if all(x in eligible for x in deps[eid]):
                eligible.add(eid)
                changed = True
    # ancestors (strict transitive) within eligible
    anc_cache = {}
    def ancestors(eid):
        if eid in anc_cache:
            return anc_cache[eid]
        res = set()
        stack = list(deps[eid])
        while stack:
            x = stack.pop()
            if x in res:
                continue
            res.add(x)
            stack.extend(deps.get(x) or [])
        anc_cache[eid] = res
        return res
    removed = set()
    for eid in eligible:
        e = unamb[eid]
        if e.get("kind") != "remove":
            continue
        targets = e.get("targets") or []
        if not isinstance(targets, list):
            continue
        anc = ancestors(eid)
        for t in targets:
            if not isinstance(t, str) or t not in eligible or t == eid:
                continue
            te = unamb[t]
            if te.get("kind") != "add":
                continue
            if te.get("key") != e.get("key"):
                continue
            if t in anc:
                removed.add(t)
    live = [eid for eid in eligible if unamb[eid].get("kind") == "add" and eid not in removed]
    return {"eligible": sorted(eligible), "live": sorted(live)}

