def solve(data):
    jobs = data["jobs"]
    setup = data["setup"]
    blackouts = sorted([tuple(b) for b in data.get("blackouts", [])])
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    deps = []
    for j in jobs:
        d = set()
        ok = True
        for x in j.get("deps", []):
            if x not in idx or x == j["id"]:
                ok = False
                break
            d.add(idx[x])
        deps.append(d if ok else None)

    def earliest(s, dur):
        changed = True
        while changed:
            changed = False
            for a, b in blackouts:
                if a >= s + dur:
                    break
                if s < b and s + dur > a:
                    s = b
                    changed = True
        return s

    best = [None]  # (-value, completion, seq)

    def consider(val, t, seq):
        key = (-val, t, seq)
        if best[0] is None or key < best[0]:
            best[0] = key

    def dfs(selected, seq, t, f, val):
        consider(val, t, list(seq))
        for i in range(n):
            if i in selected or deps[i] is None:
                continue
            if not deps[i] <= selected:
                continue
            j = jobs[i]
            s = max(j["release"], t + setup[f][j["family"]])
            s = earliest(s, j["duration"])
            c = s + j["duration"]
            if c > j["deadline"]:
                continue
            selected.add(i)
            seq.append(j["id"])
            dfs(selected, seq, c, j["family"], val + j["value"])
            seq.pop()
            selected.remove(i)

    dfs(set(), [], 0, 0, 0)
    return best[0][2]

