from bisect import bisect_right

def solve(data):
    jobs = sorted(data['jobs'], key=lambda j: j['id'])
    n = len(jobs)
    index = {j['id']: i for i, j in enumerate(jobs)}
    required = []
    for job in jobs:
        mask = 0
        for dep in job.get('deps', []):
            mask |= 1 << index.get(dep, n)
        required.append(mask)

    blackouts = []
    for a, b in sorted(data.get('blackouts', [])):
        if a >= b:
            continue
        if blackouts and a <= blackouts[-1][1]:
            blackouts[-1][1] = max(blackouts[-1][1], b)
        else:
            blackouts.append([a, b])
    ends = [b for a, b in blackouts]
    setup = data['setup']
    best_value, best_time, best_seq = 0, 0, ()

    def search(mask, time, family, value, seq):
        nonlocal best_value, best_time, best_seq
        if (value > best_value or
            (value == best_value and
             (time < best_time or (time == best_time and seq < best_seq)))):
            best_value, best_time, best_seq = value, time, seq
        for i, job in enumerate(jobs):
            bit = 1 << i
            if mask & bit or required[i] & mask != required[i]:
                continue
            start = max(job['release'], time + setup[family][job['family']])
            duration = job['duration']
            k = bisect_right(ends, start)
            while k < len(blackouts):
                a, b = blackouts[k]
                if start + duration <= a:
                    break
                start = b
                k += 1
            finish = start + duration
            if finish <= job['deadline']:
                search(mask | bit, finish, job['family'], value + job['value'], seq + (i,))

    search(0, 0, 0, 0, ())
    return [jobs[i]['id'] for i in best_seq]

